def _convert_type(self, arg, value):
    """
    Try to convert the type of input value by searching in self.types.
    :param value: str, the input value in command line
    :return: return corresponding value in self.types if convert successfully, or the input value otherwise
    >>> parser.types
    {'arg1': int}
    >>> parser._convert_type('arg1', '21')
    21
    """
    if arg in self.types:
        type_name = self.types[arg]
        # Map string type names to actual constructors
        type_constructors = {
            'int': int,
            'str': str,
            'float': float,
            'bool': bool
        }
        constructor = type_constructors.get(type_name, str)
        try:
            return constructor(value)
        except (ValueError, TypeError):
            pass
    return value

